@page "/apply"
@using sv_3d0a7c8b42174148be8c196e0ea58561.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="error-message">@_errorMessage</div>
    }

    @* Step 1: Personal Info *@
    @if (_currentStep == 0)
    {
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" @bind="_fullName" placeholder="Enter your full name" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="_email" placeholder="Enter your email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="_phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" @bind="_address" placeholder="Enter your address" />
            </div>
            <div class="form-actions">
                <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span>Validating...</span>
                    }
                    else
                    {
                        <span>Next</span>
                    }
                </button>
            </div>
        </div>
    }

    @* Step 2: Work History *@
    @if (_currentStep == 1)
    {
        <div class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <div class="work-entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="_workEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="_workEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" @bind="_workEntries[index].StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="_workEntries[index].EndDate" disabled="@_workEntries[index].IsCurrent" />
                        </div>
                    </div>
                    <div class="form-group checkbox-group">
                        <input type="checkbox" id="current-@index" @bind="_workEntries[index].IsCurrent" />
                        <label for="current-@index">I currently work here</label>
                    </div>
                    <div class="form-group">
                        <label>Description</label>
                        <textarea @bind="_workEntries[index].Description" placeholder="Describe your responsibilities..." rows="3"></textarea>
                    </div>
                </div>
            }
            <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </div>
    }

    @* Step 3: References *@
    @if (_currentStep == 2)
    {
        <div class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <div class="work-entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (_references.Count > 2)
                        {
                            <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                        }
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="_references[index].Name" placeholder="Reference name" />
                        </div>
                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="_references[index].Relationship" placeholder="e.g., Manager, Colleague" />
                        </div>
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Email *</label>
                            <input type="email" @bind="_references[index].Email" placeholder="Email address" />
                        </div>
                        <div class="form-group">
                            <label>Phone *</label>
                            <input type="tel" @bind="_references[index].Phone" placeholder="Phone number" />
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromReferences">Next</button>
            </div>
        </div>
    }

    @* Step 4: Cover Letter *@
    @if (_currentStep == 3)
    {
        <div class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter</label>
                <textarea id="coverLetter" @bind="_coverLetter" @bind:event="oninput" placeholder="Write your cover letter here..." rows="12" maxlength="2000"></textarea>
                <div class="char-count">@_coverLetter.Length / 2000 characters</div>
            </div>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </div>
    }

    @* Step 5: Review & Submit *@
    @if (_currentStep == 4)
    {
        <div class="step-content">
            @if (_isSubmitted)
            {
                <div class="confirmation">
                    <div class="confirmation-icon">&#10003;</div>
                    <h2>Application Submitted!</h2>
                    <p>Your application has been submitted successfully.</p>
                    <p class="application-id">Application ID: <strong>@_applicationId</strong></p>
                </div>
            }
            else
            {
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl>
                        <dt>Full Name</dt><dd>@_fullName</dd>
                        <dt>Email</dt><dd>@_email</dd>
                        <dt>Phone</dt><dd>@_phone</dd>
                        <dt>Address</dt><dd>@_address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="review-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                            <br />
                            <span class="review-dates">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="review-description">@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var reference in _references)
                    {
                        <div class="review-entry">
                            <strong>@reference.Name</strong> (@reference.Relationship)
                            <br />
                            <span>@reference.Email | @reference.Phone</span>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <p class="review-cover-letter">@_coverLetter</p>
                </div>

                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            }
        </div>
    }
</div>

