    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-next {
    background: #4361ee;
    color: #fff;
    margin-left: auto;
}

.btn-next:hover:not(:disabled) {
    background: #3a56d4;
}

.btn-next:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-back {
    background: #e0e0e0;
    color: #333;
}

.btn-back:hover {
    background: #d0d0d0;
}

.btn-submit {
    background: #2ec4b6;
    color: #fff;
    font-weight: 600;
    padding: 0.8rem 2rem;
}

.btn-submit:hover:not(:disabled) {
    background: #28b0a3;
}

.btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-add {
    background: transparent;
    color: #4361ee;
    border: 1px dashed #4361ee;
    width: 100%;
    padding: 0.8rem;
    margin-bottom: 1rem;
}

.btn-add:hover {
    background: #f0f4ff;
}

.btn-remove {
    background: #fee;
    color: #e63946;
    font-size: 0.8rem;
    padding: 0.3rem 0.8rem;
}

.btn-remove:hover {
    background: #fdd;
}

.btn-edit {
    background: transparent;
    color: #4361ee;
    font-size: 0.85rem;
    padding: 0.2rem 0.6rem;
    text-decoration: underline;
}

.btn-edit:hover {
    color: #3a56d4;
}

/* Error Message */
.error-message {
    background: #fee;
    color: #e63946;
    padding: 0.8rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    border: 1px solid #fcc;
    font-size: 0.9rem;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.3rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.8rem;
}

.review-header h3 {
    margin: 0;
    color: #333;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
}

.review-section dd {
    margin: 0;
    color: #333;
}

.review-entry {
    padding: 0.6rem 0;
    border-bottom: 1px solid #eee;
}

.review-entry:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    font-size: 0.9rem;
    color: #555;
    margin: 0.3rem 0 0;
}

.review-cover-letter {
    white-space: pre-wrap;
    color: #333;
    line-height: 1.6;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #2ec4b6;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.confirmation h2 {
    border: none;
    color: #2ec4b6;
}

.application-id {
    font-size: 1.1rem;
    margin-top: 1rem;
}

